const D = { energy:.6, scale:1, speed:1, density:.55, gild:.6, hue:44, x:.5, y:.5, style:'gilt', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// ILLUMINATED FOLIO — a medieval manuscript page assembling itself: a block of
// gothic textura writes in line by line, a historiated drop-cap sits in its
// jewelled ground, and a gilt vine grows down the margin, sprouting leaves,
// buds and burnished bezants. A shaft of light rakes the page so the gold leaf
// flares as it passes. When the page is complete it turns and a fresh folio in
// new colours begins. Gilt-and-lapis, azure-dominant, austere red-and-black
// rubric, or a cyan blueprint negative.
// -----------------------------------------------------------------------------

const wh = h => ((h % 360) + 360) % 360;
const style = P.style;
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4)));
const BH = Math.max(200, Math.round(BW * height / width));
const key = BW + 'x' + BH;
const eseed = (P.seed|0)*1009 + (S.folio||0)*173;
const fr = i => { const s = Math.sin(i*127.1 + eseed*0.913 + 3.1)*43758.5453; return s - Math.floor(s); };

// paperB, inkH/S/B, gold[h,s,b], jewel[h,s,b], rubric[h,s,b], neg, light
function pal(){
  if (style==='azure')     return { pB:58,pH:210,pS:16, iH:220,iS:30,iB:20, gold:[44,62,96], jewel:[224,66,52], rub:[8,70,58], neg:0, lt:[46,55,100] };
  if (style==='rubric')    return { pB:56,pH:40,pS:14,  iH:20,iS:8,iB:14,   gold:[38,20,60], jewel:[8,72,54],  rub:[6,78,54], neg:0, lt:[40,25,100] };
  if (style==='blueprint') return { pB:24,pH:210,pS:52, iH:190,iS:14,iB:92, gold:[186,50,100], jewel:[200,60,70], rub:[195,55,96], neg:1, lt:[196,50,100] };
  return { pB:52,pH:wh(P.hue-2),pS:22, iH:28,iS:14,iB:18, gold:[46,66,98], jewel:[262,58,50], rub:[6,80,56], neg:0, lt:[48,60,100] }; // gilt
}
const C = pal();

// ---- vellum ground ----------------------------------------------------------
if (!S.paper || S.pkey!==key || S.pstyle!==style || S.pseed!==(P.seed|0)){
  S.pkey=key; S.pstyle=style; S.pseed=(P.seed|0);
  const pg=createGraphics(BW,BH); pg.colorMode(HSB,360,100,100,100); pg.noStroke();
  pg.background(C.pH,C.pS,C.pB);
  pg.blendMode(C.neg?ADD:MULTIPLY);
  for (let i=0;i<80;i++){ pg.fill(C.pH,C.pS*0.7, C.neg?26+fr(i)*18:100-(7+fr(i)*13),9); pg.ellipse(fr(i*3+1)*BW,fr(i*5+2)*BH,BW*(0.1+fr(i*7)*0.3),BW*(0.1+fr(i*7)*0.25)); }
  pg.blendMode(BLEND);
  for (let i=0;i<2400;i++){ pg.fill(C.pH,C.pS,C.neg?C.pB+fr(i)*22:C.pB-fr(i)*20,5); pg.rect(fr(i*2.1+700)*BW,fr(i*3.7+701)*BH,1.2,1.2); }
  S.paper=pg;
  const vg=createGraphics(BW,BH); vg.colorMode(HSB,360,100,100,100); vg.clear();
  const gc=vg.drawingContext; const rg=gc.createRadialGradient(BW/2,BH/2,BH*0.24,BW/2,BH/2,BH*0.82);
  rg.addColorStop(0,'rgba(0,0,0,0)'); rg.addColorStop(0.6,'rgba(0,0,0,0.10)'); rg.addColorStop(1,'rgba(0,0,0,0.44)');
  gc.fillStyle=rg; gc.fillRect(0,0,BW,BH); S.vig=vg;
}

// ---- layout + structure -----------------------------------------------------
const dens=P.density;
const mL=BW*0.12, mR=BW*0.80, mT=BH*0.12, mB=BH*0.90;
const lineH=BH*(0.052-dens*0.014)/Math.max(0.6,P.scale*0.85+0.15);
const xh=lineH*0.62;
const nLines=Math.max(6,Math.floor((mB-mT)/lineH));
const capRows=4;
if (!S.txt || S.tkey!==key || S.tstyle!==style || S.tfolio!==(S.folio||0) || S.tseed!==(P.seed|0) || S.tdens!==Math.round(dens*20) || S.tscale!==Math.round(P.scale*20)){
  S.tkey=key; S.tstyle=style; S.tfolio=(S.folio||0); S.tseed=(P.seed|0); S.tdens=Math.round(dens*20); S.tscale=Math.round(P.scale*20);
  // gothic textura lines: each is an array of minims (short vertical strokes) with word gaps
  const lines=[];
  for (let li=0; li<nLines; li++){
    const yb=mT+xh+li*lineH;
    const indent = (li<capRows) ? mL + (mR-mL)*0.30 : mL;   // wrap around drop-cap
    const rightX = mR - fr(li*7+2)*(mR-mL)*0.06;
    const minims=[];
    let x=indent; const mw=xh*0.42;
    while (x<rightX-mw){
      const wl = 2+Math.floor(fr(li*13+minims.length*3+4)*7);
      for (let m=0;m<wl && x<rightX-mw; m++){ minims.push({x, yb, asc: fr(li*17+x)>0.9, desc: fr(li*19+x)>0.9}); x+=mw*(0.85+fr(li*3+x)*0.3); }
      x += mw*(0.9+fr(li*5+x)*0.7);   // word gap
    }
    lines.push({yb, minims, mw});
  }
  // drop cap
  S.cap = { ch: String.fromCharCode(65+Math.floor(fr(99)*26)), x:mL, y:mT, w:(mR-mL)*0.26, h:lineH*capRows*0.92 };
  // margin vine path
  const vine=[]; const vx0=BW*0.86, vsteps=44;
  for (let s=0;s<=vsteps;s++){ const f=s/vsteps; const vy=mT+f*(mB-mT); const vx=vx0+Math.sin(f*7.5+fr(3)*6)*BW*0.03; vine.push({x:vx,y:vy,f,leaf: (s%3===0), side: s%2}); }
  S.vine=vine;
  S.txtL=lines; S.prog=0; S.phase='write'; S.dwell=0; S.fade=100;
  const ig=createGraphics(BW,BH); ig.colorMode(HSB,360,100,100,100); ig.clear(); S.ink=ig; S.drawn=0;
}

// draw a gothic line into ink buffer
function inkLine(g, ln){
  const dark=0.5+P.energy*0.7;
  g.stroke(C.iH,C.iS,C.iB, Math.min(100,70+dark*30)); g.strokeCap(SQUARE);
  for (const m of ln.minims){
    const h=xh*(m.asc?1.5:1)*(m.desc?1.4:1);
    const top=m.yb-xh*(m.asc?1.5:1), bot=m.yb+(m.desc?xh*0.5:0);
    g.strokeWeight(ln.mw*0.5); g.line(m.x,top,m.x,bot);
    // serif feet
    g.strokeWeight(ln.mw*0.34); g.line(m.x-ln.mw*0.22,bot,m.x+ln.mw*0.22,bot);
  }
}

// ---- advance ----------------------------------------------------------------
const total=S.txtL.length;
const spd=0.35+P.speed*1.1;
if (S.phase==='write'){
  S.prog += (spd*2.1)/(K.fps||60);
  const upto=Math.min(total,Math.floor(S.prog));
  while (S.drawn<upto){ inkLine(S.ink,S.txtL[S.drawn]); S.drawn++; }
  if (S.drawn>=total && S.prog>=total+1.2){ S.phase='dwell'; S.dwell=0; }
} else if (S.phase==='dwell'){ S.dwell+=1/(K.fps||60); if (S.dwell>2.6/(0.4+P.speed*0.8)) S.phase='fade'; }
else if (S.phase==='fade'){ S.fade-=120/(K.fps||60); if (S.fade<=0){ S.folio=(S.folio||0)+1; S.txt=null; S.txtL=null; } }

// vine growth tracks progress (grows through the whole write phase + a bit)
const vineProg = Math.min(1, S.prog/(total*0.9+0.001));

// ---- render -----------------------------------------------------------------
const t=K.t; const sxr=width/BW, syr=height/BH;
const dx=Math.sin(t*0.12)*width*0.005+Math.sin(t*0.30+1.1)*width*0.004, dy=Math.cos(t*0.10)*height*0.005;
const ox=(P.x-0.5)*width*0.12, oy=(P.y-0.5)*height*0.12;
const lpx=(Math.sin(t*0.17)*0.5+0.5)*0.6+(Math.sin(t*0.049+2)*0.5+0.5)*0.4;   // light sweep 0..1
const pageA = S.phase==='fade'? Math.max(0,S.fade):100;

push(); translate(dx+ox,dy+oy);
if (S.paper) image(S.paper,0,0,width,height);
if (S.ink){ push(); tint(0,0,100,pageA); image(S.ink,0,0,width,height); pop(); }

if (S.txtL){
  // gilt helper: brightness boosted when the light sweep is near
  const gild=P.gild;
  const nearGild = xp => { const d=Math.abs(xp/width - lpx); return Math.max(0, 1-d*3.2); };
  // ---- drop cap ----
  const cp=S.cap; const cx=cp.x*sxr, cy=cp.y*syr, cw=cp.w*sxr, chh=cp.h*syr;
  push();
  const cn=nearGild(cp.x*sxr+cw/2);
  noStroke(); fill(C.jewel[0],C.jewel[1],C.jewel[2]*(pageA/100)); rect(cx,cy,cw,chh);
  // gold ground panel inset
  fill(C.gold[0],C.gold[1]*(0.7+0.3*cn),Math.min(100,C.gold[2]*(0.7+0.4*cn))*(pageA/100)); rect(cx+cw*0.10,cy+chh*0.10,cw*0.80,chh*0.80);
  // interlace filaments
  stroke(C.jewel[0],C.jewel[1]*0.7,C.jewel[2]*1.3,60*(pageA/100)); strokeWeight(Math.max(0.6,cw*0.02)); noFill();
  for (let i=0;i<5;i++){ const yy=cy+chh*(0.16+i*0.16); beginShape(); for(let s=0;s<=8;s++){ const xx=cx+cw*(0.14+s/8*0.72); vertex(xx, yy+Math.sin(s*1.6+i)*chh*0.05);} endShape(); }
  // big letter
  noStroke(); textAlign(CENTER,CENTER); textFont('Georgia'); textStyle(BOLD); textSize(chh*0.62);
  fill(C.iH,C.iS+20,C.iB, 70*(pageA/100)); text(cp.ch, cx+cw/2+1.5, cy+chh/2+1.5);
  fill(C.jewel[0],C.jewel[1],Math.min(100,C.jewel[2]*1.5), pageA); text(cp.ch, cx+cw/2, cy+chh/2);
  textStyle(NORMAL);
  pop();
  // ---- margin vine (grows) ----
  const vn=S.vine; const grown=Math.floor(vn.length*vineProg);
  push(); strokeCap(ROUND);
  for (let i=1;i<grown;i++){ const a=vn[i-1],b=vn[i];
    stroke(C.gold[0],C.gold[1]*0.5,C.gold[2]*(0.55+0.45*nearGild(b.x*sxr)),80*(pageA/100)); strokeWeight(Math.max(1,BW*0.006*sxr));
    line(a.x*sxr,a.y*syr,b.x*sxr,b.y*syr);
    if (b.leaf){ const cn2=nearGild(b.x*sxr); noStroke();
      fill((b.side? C.jewel[0]:130), b.side?C.jewel[1]:55, (b.side?C.jewel[2]:56)*(0.7+0.4*cn2), 80*(pageA/100));
      const lx=b.x+(b.side?1:-1)*BW*0.028, ly=b.y;
      push(); translate(lx*sxr,ly*syr); rotate((b.side?0.6:-0.6)); ellipse(0,0,BW*0.05*sxr,BW*0.022*syr); pop();
      // bezant
      fill(C.gold[0],C.gold[1]*(0.6+0.3*cn2),Math.min(100,C.gold[2]*(0.7+0.4*cn2)),90*(pageA/100)); ellipse(b.x*sxr,b.y*syr,BW*0.012*sxr,BW*0.012*syr);
      stroke(0,0,0); noStroke();
    }
  }
  pop();
  // growing tendril tip glint (live motion)
  if (S.phase==='write' && grown>1){ const tip=vn[Math.min(vn.length-1,grown)]; noStroke(); fill(C.lt[0],C.lt[1]*0.4,C.lt[2],45); ellipse(tip.x*sxr,tip.y*syr,BW*0.02*sxr,BW*0.02*syr); }
}
pop();

// raking light band
push(); blendMode(ADD); noStroke();
const glowA=(9+P.energy*12+A.rms*8)*(C.neg?0.7:1);
for (let b=0;b<5;b++){ fill(C.lt[0],C.lt[1]*(0.5+0.1*b),C.lt[2],glowA*(1-b/5)*0.42); rect(lpx*width-width*0.17,-height*0.05,width*(0.34)*(0.4+0.15*b),height*1.1); }
blendMode(BLEND); pop();

if (S.vig){ push(); blendMode(MULTIPLY); image(S.vig,dx+ox,dy+oy,width,height); blendMode(BLEND); pop(); }
if (P.alpha<100){ push(); noStroke(); fill(C.pH,C.pS,C.pB,100-Math.max(0,Math.min(100,P.alpha))); rect(0,0,width,height); pop(); }
blendMode(BLEND); noTint(); textStyle(NORMAL); drawingContext.shadowBlur=0;
